1	/**
2	 * Claude executor entrypoint — ABI-conformant.
3	 *
4	 * Reads ExecutorInput from environment variables, runs two-phase startup,
5	 * spawns `claude -p`, and writes ExecutorResult to result.json at RESULT_PATH.
6	 *
7	 * Formal ABI env vars (from ExecutorInput):
8	 *   TASK_ID, FEATURE_ID, WORKSPACE_ID, HANDLE
9	 *   TASK_REPO_URL, TASK_REPO_BRANCH, TASK_BASE_BRANCH
10	 *   EXECUTOR_WORKDIR, MGMT_REPO_URL
11	 *   RESULT_PATH, KIND (optional: impl|fix|reviewer|rebase — defaults to impl)
12	 *   BUDGET_TOKENS (optional)
13	 *   SSH_PRIVATE_KEY, GITHUB_TOKEN
14	 *
15	 * Derived paths (not passed by orchestrator — executor sets them in process.env):
16	 *   WORKSPACE_ROOT   = ${EXECUTOR_WORKDIR}/mgmt  (management repo clone, read-only)
17	 *   TASK_REPO_PATH   = ${EXECUTOR_WORKDIR}/impl  (implementation repo)
18	 *
19	 * Day-1 single-container extras (not in formal ABI — passed by SubProcessAdapter):
20	 *   TASK_BRANCH        — management repo feature branch for git commits
21	 *   GIT_AUTHOR_EMAIL   — for commit identity
22	 *   GIT_AUTHOR_NAME    — for commit identity
23	 *   WORKFLOW_LOCAL_PATH — workflow repo root for skills setup
24	 *   MAX_TURNS          — max claude CLI turns (default: 200)
25	 *   LOG_SINK_ENABLED   — "1" to flush JSONL log to management repo
26	 *   MCP_RAG_URL        — optional RAG server URL for MCP registration
27	 *   FIGMA_PERSONAL_ACCESS_TOKEN — optional Figma MCP
28	 *   GITNEXUS_MCP_URL   — optional GitNexus code-graph MCP server URL
29	 *   CLAUDE_AGENT_RUNTIME — injected as "1" for agent detection
30	 */
31	
32	import { spawn, execSync } from "node:child_process";
33	import {
34	  mkdirSync,
35	  appendFileSync,
36	  readFileSync,
37	  writeFileSync,
38	  existsSync,
39	  readdirSync,
40	  rmSync,
41	  copyFileSync,
42	  lstatSync,
43	} from "node:fs";
44	import { join, dirname } from "node:path";
45	import { homedir } from "node:os";
46	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
47	import type { ExecutorResult } from "@workflow/runtime-abi";
48	import { isValidResult } from "@workflow/runtime-abi";
49	import { extractTokenUsage } from "./token-usage.js";
50	import { extractRagQueries } from "./rag-audit.js";
51	import { extractGitNexusQueries } from "./gitnexus-audit.js";
52	import { enforceInReviewRequiresPrUrl } from "./enforce-pr-url.js";
53	import { runRecovery, parseGitHubCoords, isMaxTurnsExit, type SpawnResult } from "./recovery.js";
54	import {
55	  generateContinuationBriefing,
56	  collectGitState,
57	  fetchOpenPrUrl,
58	} from "./briefing/continuation-context.js";
59	import { resolveSSHKey } from "./resolve-ssh-key.js";
60	import { redactSecrets } from "./redact-secrets.js";
61	import { buildGitEnv } from "./git-env.js";
62	import { flushLog } from "./flush-log.js";
63	import { ensureImplFeatureBranch } from "./impl-feature-branch.js";
64	import { setupGlobalSettings } from "./setup-global-settings.js";
65	import { buildBriefing, type BuildBriefingOpts, type BriefingKind } from "./briefing/index.js";
66	
67	// ── Helpers ───────────────────────────────────────────────────────────────────
68	
69	function requireEnv(name: string): string {
70	  const val = process.env[name];
71	  if (!val) throw new Error(`Required env var ${name} is not set`);
72	  return val;
73	}
74	
75	function emit(event: Record<string, unknown>): void {
76	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
77	}
78	
79	/**
80	 * Materialize the implementation repo at taskRepoPath:
81	 *   - If path exists and origin matches URL: fetch + checkout + pull
82	 *   - Otherwise: clone fresh
83	 */
84	function materializeRepo(
85	  taskRepoUrl: string,
86	  taskRepoBranch: string,
87	  taskRepoPath: string,
88	  sshKeyPath: string | undefined,
89	): void {
90	  const env = buildGitEnv(sshKeyPath);
91	  const opts = { env, stdio: "pipe" as const };
92	
93	  if (existsSync(join(taskRepoPath, ".git"))) {
94	    let originUrl = "";
95	    try {
96	      originUrl = execSync(`git -C "${taskRepoPath}" remote get-url origin`, {
97	        ...opts, encoding: "utf-8",
98	      }).trim();
99	    } catch { /* no remote — fall through to clone */ }
100	
101	    if (originUrl === taskRepoUrl) {
102	      execSync(`git -C "${taskRepoPath}" fetch origin`, opts);
103	      // Discard local changes from a previous session before checkout.
104	      try { execSync(`git -C "${taskRepoPath}" checkout -- .`, opts); } catch { /* ignore */ }
105	      try {
106	        execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
107	      } catch {
108	        execSync(`git -C "${taskRepoPath}" checkout -b "${taskRepoBranch}"`, opts);
109	      }
110	      try {
111	        execSync(
112	          `git -C "${taskRepoPath}" pull --ff-only origin "${taskRepoBranch}"`,
113	          opts,
114	        );
115	      } catch {
116	        emit({ type: "repo_pull_diverged", task_repo: taskRepoPath, branch: taskRepoBranch, note: "ff-only failed — working on checked-out ref without latest origin commits" });
117	      }
118	      return;
119	    }
120	  }
121	
122	  // Clone fresh.
123	  mkdirSync(dirname(taskRepoPath), { recursive: true });
124	  if (existsSync(taskRepoPath)) {
125	    rmSync(taskRepoPath, { recursive: true, force: true });
126	  }
127	  execSync(`git clone "${taskRepoUrl}" "${taskRepoPath}"`, opts);
128	  try {
129	    execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
130	  } catch {
131	    execSync(`git -C "${taskRepoPath}" checkout -b "${taskRepoBranch}"`, opts);
132	  }
133	}
134	
135	/**
136	 * Materialize the management repo at mgmtDir on the task branch.
137	 * Idempotent: if the dir already contains a valid clone of the same URL,
138	 * runs fetch + checkout -B <taskBranch> origin/<taskBranch> instead of a fresh clone.
139	 * Falls back to main if the task branch doesn't exist on origin yet.
140	 */
141	function materializeMgmtRepo(
142	  mgmtRepoUrl: string,
143	  mgmtDir: string,
144	  sshKeyPath: string | undefined,
145	  taskBranch: string,
146	): void {
147	  const env = buildGitEnv(sshKeyPath);
148	  const opts = { env, stdio: "pipe" as const };
149	
150	  const checkoutTaskBranch = (dir: string): void => {
151	    try {
152	      execSync(`git -C "${dir}" checkout -B "${taskBranch}" "origin/${taskBranch}"`, opts);
153	    } catch (taskBranchErr) {
154	      // Task branch not on origin yet — fall back to main.
155	      try {
156	        execSync(`git -C "${dir}" checkout main`, opts);
157	      } catch (mainCheckoutErr) {
158	        emit({ type: "mgmt_repo_checkout_failed", mgmt_dir: dir, branch: "main", details: String(mainCheckoutErr) });
159	      }
160	      try {
161	        execSync(`git -C "${dir}" pull --ff-only origin main`, opts);
162	      } catch {
163	        emit({ type: "mgmt_repo_pull_diverged", mgmt_dir: dir, note: "ff-only failed — using checked-out ref", task_branch_err: String(taskBranchErr) });
164	      }
165	    }
166	  };
167	
168	  if (existsSync(join(mgmtDir, ".git"))) {
169	    let originUrl = "";
170	    try {
171	      originUrl = execSync(`git -C "${mgmtDir}" remote get-url origin`, {
172	        ...opts, encoding: "utf-8",
173	      }).trim();
174	    } catch { /* no remote — fall through to clone */ }
175	
176	    if (originUrl === mgmtRepoUrl) {
177	      execSync(`git -C "${mgmtDir}" fetch origin`, opts);
178	      checkoutTaskBranch(mgmtDir);
179	      return;
180	    }
181	  }
182	
183	  mkdirSync(dirname(mgmtDir), { recursive: true });
184	  if (existsSync(mgmtDir)) {
185	    rmSync(mgmtDir, { recursive: true, force: true });
186	  }
187	  execSync(`git clone "${mgmtRepoUrl}" "${mgmtDir}"`, opts);
188	  checkoutTaskBranch(mgmtDir);
189	}
190	
191	/**
192	 * Turn budget for the E2 continuation retry — the focused re-spawn that runs
193	 * after a clean exit without result.json. Intentionally low: the retry's only
194	 * job is to write result.json based on existing branch state, not to do real
195	 * implementation work. Override via env var if you need more headroom.
196	 */
197	const DEFAULT_CONTINUATION_MAX_TURNS = 20;
198	
199	const TOOLCHAIN_MARKERS: Array<{ file: string; tool: string }> = [
200	  { file: "yarn.lock",        tool: "yarn"    },
201	  { file: "pnpm-lock.yaml",   tool: "pnpm"    },
202	  { file: "bun.lockb",        tool: "bun"     },
203	  { file: "go.mod",           tool: "go"      },
204	  { file: "requirements.txt", tool: "python3" },
205	  { file: "pyproject.toml",   tool: "python3" },
206	  { file: "Cargo.toml",       tool: "cargo"   },
207	];
208	
209	function checkRequiredTools(taskRepoPath: string): string[] {
210	  const missing: string[] = [];
211	  const checked = new Set<string>();
212	  for (const { file, tool } of TOOLCHAIN_MARKERS) {
213	    if (checked.has(tool)) continue;
214	    if (!existsSync(join(taskRepoPath, file))) continue;
215	    checked.add(tool);
216	    try {
217	      execSync(`which ${tool}`, { stdio: "pipe" });
218	    } catch {
219	      missing.push(tool);
220	    }
221	  }
222	  return missing;
223	}
224	
225	function copyWorkspaceClaude(workspaceRoot: string): void {
226	  const src = join(workspaceRoot, "CLAUDE.md");
227	  if (!existsSync(src)) return;
228	  const destDir = join(homedir(), ".claude");
229	  mkdirSync(destDir, { recursive: true });
230	  copyFileSync(src, join(destDir, "CLAUDE.md"));
231	}
232	
233	function copyDirRecursive(src: string, dest: string): void {
234	  mkdirSync(dest, { recursive: true });
235	  for (const entry of readdirSync(src)) {
236	    const srcPath = join(src, entry);
237	    const destPath = join(dest, entry);
238	    const stat = lstatSync(srcPath);
239	    if (stat.isDirectory()) {
240	      copyDirRecursive(srcPath, destPath);
241	    } else if (stat.isFile()) {
242	      copyFileSync(srcPath, destPath);
243	    }
244	  }
245	}
246	
247	function setupGlobalSkills(workspaceRoot: string, workflowLocalPath: string): void {
248	  const globalSkillsDir = join(homedir(), ".claude", "skills");
249	  if (existsSync(globalSkillsDir)) {
250	    rmSync(globalSkillsDir, { recursive: true, force: true });
251	  }
252	  mkdirSync(globalSkillsDir, { recursive: true });
253	
254	  const copySkillsFrom = (sourceDir: string): void => {
255	    if (!existsSync(sourceDir)) return;
256	    let entries: string[];
257	    try { entries = readdirSync(sourceDir); } catch { return; }
258	    for (const entry of entries) {
259	      const srcPath = join(sourceDir, entry);
260	      try {
261	        const stat = lstatSync(srcPath);
262	        if (!stat.isDirectory()) continue;
263	        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
264	      } catch (e) {
265	        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
266	      }
267	    }
268	  };
269	
270	  copySkillsFrom(join(workflowLocalPath, "technical_skills"));
271	  copySkillsFrom(join(workflowLocalPath, "workflow_skills"));
272	
273	  const wsSkillsDir = join(workspaceRoot, ".claude", "skills");
274	  if (existsSync(wsSkillsDir)) {
275	    let entries: string[];
276	    try { entries = readdirSync(wsSkillsDir); } catch { entries = []; }
277	    for (const entry of entries) {
278	      if (entry === ".gitignore") continue;
279	      const srcPath = join(wsSkillsDir, entry);
280	      try {
281	        const stat = lstatSync(srcPath);
282	        if (stat.isSymbolicLink() || !stat.isDirectory()) continue;
283	        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
284	      } catch (e) {
285	        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
286	      }
287	    }
288	  }
289	}
290	
291	function writeResult(resultPath: string, result: ExecutorResult): void {
292	  mkdirSync(dirname(resultPath), { recursive: true });
293	  writeFileSync(resultPath, JSON.stringify(result), "utf-8");
294	}
295	
296	// ── Main ──────────────────────────────────────────────────────────────────────
297	
298	async function main(): Promise<void> {
299	  // ── Read formal ABI env vars ────────────────────────────────────────────────
300	  let taskId: string;
301	  let featureId: string;
302	  let taskRepoUrl: string;
303	  let taskRepoBranch: string;
304	  let executorWorkdir: string;
305	  let mgmtRepoUrl: string;
306	  let resultPath: string;
307	  let sshKeyPath: string | undefined;
308	  let githubToken: string;
309	
310	  try {
311	    taskId = requireEnv("TASK_ID");
312	    featureId = requireEnv("FEATURE_ID");
313	    taskRepoUrl = requireEnv("TASK_REPO_URL");
314	    taskRepoBranch = requireEnv("TASK_REPO_BRANCH");
315	    executorWorkdir = requireEnv("EXECUTOR_WORKDIR");
316	    mgmtRepoUrl = requireEnv("MGMT_REPO_URL");
317	    resultPath = requireEnv("RESULT_PATH");
318	    githubToken = process.env.GITHUB_TOKEN ?? "";
319	    sshKeyPath = resolveSSHKey({ SSH_PRIVATE_KEY: process.env.SSH_PRIVATE_KEY }).sshKeyPath;
320	  } catch (e) {
321	    emit({ type: "executor_fatal", details: (e as Error).message });
322	    process.exit(1);
323	  }
324	
325	  const budgetTokensStr = process.env.BUDGET_TOKENS;
326	  const budgetTokens = budgetTokensStr ? parseInt(budgetTokensStr, 10) : undefined;
327	
328	  const implDir = join(executorWorkdir, "impl");
329	  const mgmtDir = join(executorWorkdir, "mgmt");
330	
331	  // Day-1 single-container extras.
332	  const workspaceRoot = mgmtDir;
333	  const taskBranch = process.env.TASK_BRANCH ?? `feature/${featureId}-${taskId}`;
334	  const gitAuthorEmail = process.env.GIT_AUTHOR_EMAIL ?? "agent@unknown";
335	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
336	  const workflowLocalPath = process.env.WORKFLOW_LOCAL_PATH ?? "";
337	  const maxTurns = parseInt(process.env.MAX_TURNS ?? "200", 10);
338	  const logSinkEnabled = process.env.LOG_SINK_ENABLED === "1";
339	  const mcpRagUrl = process.env.MCP_RAG_URL;
340	  const figmaToken = process.env.FIGMA_PERSONAL_ACCESS_TOKEN;
341	  const gitnexusMcpUrl = process.env.GITNEXUS_MCP_URL;
342	  const implementationModel = process.env.IMPLEMENTATION_MODEL;
343	  const executorKind = (process.env.EXECUTOR_KIND ?? "impl") as "impl" | "review";
344	  const implPrUrl = process.env.IMPL_PR_URL ?? "";
345	  const briefingKind = (process.env.KIND as BriefingKind | undefined) ??
346	    (executorKind === "review" ? "reviewer" : "impl");
347	
348	  const runStartIso = new Date().toISOString();
349	
350	  // ── 1. Two-phase repo materialization ─────────────────────────────────────
351	  // Phase 1: management repo — checked out to the task branch so $WORKSPACE_ROOT
352	  // has the current task YAML (on the task branch, not main).
353	  try {
354	    materializeMgmtRepo(mgmtRepoUrl, mgmtDir, sshKeyPath, taskBranch);
355	    process.env.WORKSPACE_ROOT = mgmtDir;
356	  } catch (e) {
357	    const details = `mgmt repo materialization failed: ${String(e)}`;
358	    emit({ type: "executor_fatal", task_id: taskId, details });
359	    writeResult(resultPath, {
360	      terminal_status: "failed",
361	      blocked_reason: `mgmt_repo_materialization_failed: ${String(e)}`,
362	    });
363	    process.exit(0);
364	  }
365	
366	  // Phase 2: implementation repo
367	  const taskRepoBaseBranch = process.env.TASK_REPO_BASE_BRANCH ?? "";
368	  const taskBaseBranch = process.env.TASK_BASE_BRANCH ?? "";
369	  try {
370	    materializeRepo(taskRepoUrl, taskRepoBranch, implDir, sshKeyPath);
371	    process.env.TASK_REPO_PATH = implDir;
372	  } catch (e) {
373	    const details = `impl repo materialization failed: ${String(e)}`;
374	    emit({ type: "executor_fatal", task_id: taskId, details });
375	    writeResult(resultPath, {
376	      terminal_status: "failed",
377	      blocked_reason: `repo_materialization_failed: ${String(e)}`,
378	    });
379	    process.exit(0);
380	  }
381	
382	  // Ensure `feature/{featureId}` exists on the impl repo remote so PR creation
383	  // can target it. Uses TASK_REPO_BASE_BRANCH (the repo's root base branch, e.g.
384	  // "main") as the push source — not TASK_BASE_BRANCH, which is the feature branch
385	  // itself and cannot be used as its own creation source.
386	  if (taskRepoBaseBranch) {
387	    ensureImplFeatureBranch(featureId, taskRepoBaseBranch, implDir, sshKeyPath, emit);
388	  }
389	
390	  // ── 2. Toolchain pre-flight check ──────────────────────────────────────────
391	  const missingTools = checkRequiredTools(implDir);
392	  if (missingTools.length > 0) {
393	    const details = `missing tools: ${missingTools.join(", ")}`;
394	    emit({ type: "preflight_failed", task_id: taskId, feature_id: featureId, details });
395	    writeResult(resultPath, {
396	      terminal_status: "blocked",
397	      blocked_reason: "missing_tool",
398	      blocked_suggestion: `Install missing tools in the executor image: ${missingTools.join(", ")}`,
399	    });
400	    process.exit(0);
401	  }
402	
403	  // ── 3. Workspace rules + global skills ─────────────────────────────────────
404	  if (workspaceRoot) copyWorkspaceClaude(workspaceRoot);
405	  if (workspaceRoot && workflowLocalPath) setupGlobalSkills(workspaceRoot, workflowLocalPath);
406	  if (workflowLocalPath) setupGlobalSettings(workflowLocalPath, emit);
407	
408	  // ── 4. Build briefing (self-contained — reads workspace docs from mgmt repo) ──
409	  let briefingContent: string;
410	  try {
411	    const reviewCycleCount = parseInt(process.env.REVIEW_CYCLE_COUNT ?? "0", 10);
412	    const maxReviewCycles = parseInt(process.env.MAX_REVIEW_CYCLES ?? "3", 10);
413	    // Read task YAML from mgmt repo to resolve human-readable repo ID.
414	    let taskRepo = featureId;
415	    try {
416	      const taskYamlPath = join(mgmtDir, "docs", "features", featureId, "tasks", `${taskId}.yaml`);
417	      const taskYaml = parseYaml(readFileSync(taskYamlPath, "utf-8")) as Record<string, unknown>;
418	      if (typeof taskYaml["repo"] === "string") taskRepo = taskYaml["repo"];
419	    } catch { /* fall through to default */ }
420	    const baseOpts = {
421	      taskId,
422	      featureId,
423	      taskBranch,
424	      taskRepo,
425	      taskRepoRoot: implDir,
426	      workspaceRoot: mgmtDir,
427	      gitAuthorEmail,
428	      gitAuthorName,
429	      implementationModel: implementationModel ?? "claude-sonnet-4-6",
430	      resultPath,
431	    };
432	    let briefingOpts: BuildBriefingOpts;
433	    if (briefingKind === "reviewer") {
434	      briefingOpts = {
435	        kind: "reviewer",
436	        ...baseOpts,
437	        prUrl: implPrUrl,
438	        reviewerModel: implementationModel ?? "claude-sonnet-4-6",
439	        reviewCycleCount,
440	        maxReviewCycles,
441	      };
442	    } else if (briefingKind === "fix") {
443	      briefingOpts = {
444	        kind: "fix",
445	        ...baseOpts,
446	        prUrl: implPrUrl,
447	        mode: "review-fixes",
448	        reviewUrl: process.env.REVIEW_URL ?? "",
449	      };
450	    } else if (briefingKind === "rebase") {
451	      // Rebase dispatch uses the same fix-briefing infrastructure; mode is
452	      // forced to "conflict-resolution" inside buildBriefing.
453	      briefingOpts = {
454	        kind: "rebase",
455	        ...baseOpts,
456	        prUrl: implPrUrl,
457	        mode: "conflict-resolution",
458	        taskBaseBranch,
459	      };
460	    } else {
461	      briefingOpts = { kind: "impl", ...baseOpts };
462	    }
463	    briefingContent = buildBriefing(mgmtDir, briefingOpts);
464	  } catch (e) {
465	    emit({ type: "executor_fatal", task_id: taskId, details: `briefing build failed: ${String(e)}` });
466	    writeResult(resultPath, {
467	      terminal_status: "failed",
468	      blocked_reason: `briefing_build_failed: ${String(e)}`,
469	    });
470	    process.exit(0);
471	  }
472	
473	  // Append hard-stop rule for missing tools.
474	  const effectiveBriefing =
475	    briefingContent +
476	    `\n\n## Hard stop rule — missing tools\nIf any shell command exits with code 127 ("command not found"), do NOT attempt to install it or work around it. Immediately write \`{"terminal_status":"blocked","blocked_reason":"missing_tool"}\` to \`${resultPath}\` and stop.`;
477	
478	  // ── 5. Build MCP config ─────────────────────────────────────────────────────
479	  const mcpArgs: string[] = [];
480	  if (mcpRagUrl || figmaToken || gitnexusMcpUrl) {
481	    const mcpConfig: { mcpServers: Record<string, unknown> } = { mcpServers: {} };
482	    if (mcpRagUrl) {
483	      mcpConfig.mcpServers["rag-server"] = { type: "sse", url: `${mcpRagUrl}/sse` };
484	    }
485	    if (gitnexusMcpUrl) {
486	      mcpConfig.mcpServers["gitnexus"] = { type: "sse", url: `${gitnexusMcpUrl}/sse` };
487	    }
488	    if (figmaToken) {
489	      mcpConfig.mcpServers["figma"] = {
490	        type: "stdio",
491	        command: "npx",
492	        args: ["-y", "@figma/mcp-server"],
493	        env: { FIGMA_PERSONAL_ACCESS_TOKEN: figmaToken },
494	      };
495	    }
496	    const mcpConfigPath = `/tmp/mcp-config-${taskId}.json`;
497	    writeFileSync(mcpConfigPath, JSON.stringify(mcpConfig));
498	    mcpArgs.push("--mcp-config", mcpConfigPath);
499	  }
500	
501	  if (mcpRagUrl) {
502	    emit({ type: "rag_mcp_registered", url: mcpRagUrl });
503	  } else {
504	    emit({ type: "rag_mcp_unavailable", reason: "MCP_RAG_URL not set" });
505	  }
506	
507	  // ── 6. Spawn claude — wrapped in try/finally for Layer 1 recovery ───────────
508	  // PYTHONUSERBASE redirects all `pip install --user` into the executor's own
509	  // directory, preventing cross-executor pip registration conflicts when two
510	  // executors work on the same Python repo concurrently (e.g. T2 then T4 on cycle).
511	  const pybase = join(executorWorkdir, "pybase");
512	  const claudeEnv = {
513	    ...buildGitEnv(sshKeyPath),
514	    CLAUDE_AGENT_RUNTIME: "1",
515	    RESULT_PATH: resultPath,
516	    GITHUB_TOKEN: githubToken,
517	    TASK_REPO_PATH: implDir,
518	    PYTHONUSERBASE: pybase,
519	    PATH: `${join(pybase, "bin")}:${process.env.PATH ?? "/usr/local/bin:/usr/bin:/bin"}`,
520	  };
521	
522	  /**
523	   * Spawn `claude -p` with the given briefing and turn limit. Captures stdout
524	   * into a buffer (also piped to this process's stdout) and installs a watchdog
525	   * that SIGTERMs the child 30s after it emits its final "result" event.
526	   */
527	  async function spawnClaude(briefing: string, turns: number): Promise<SpawnResult> {
528	    return await new Promise<SpawnResult>((resolve) => {
529	      const stdoutChunks: string[] = [];
530	
531	      const child = spawn(
532	        "claude",
533	        [
534	          "-p", briefing,
535	          "--max-turns", String(turns),
536	          "--output-format", "stream-json",
537	          "--verbose",
538	          "--dangerously-skip-permissions",
539	          ...(implementationModel ? ["--model", implementationModel] : []),
540	          ...mcpArgs,
541	        ],
542	        { cwd: implDir, env: claudeEnv },
543	      );
544	
545	      child.stdout.setEncoding("utf-8");
546	      child.stderr.setEncoding("utf-8");
547	
548	      let resultWatchdog: ReturnType<typeof setTimeout> | null = null;
549	      let stdoutLineBuf = "";
550	      child.stdout.on("data", (chunk: string) => {
551	        stdoutChunks.push(chunk);
552	        process.stdout.write(chunk);
553	        if (resultWatchdog === null) {
554	          stdoutLineBuf += chunk;
555	          const lines = stdoutLineBuf.split("\n");
556	          stdoutLineBuf = lines.pop() ?? "";
557	          for (const line of lines) {
558	            if (line.includes('"type":"result"')) {
559	              resultWatchdog = setTimeout(() => {
560	                if (!child.killed) child.kill("SIGTERM");
561	              }, 30_000);
562	              break;
563	            }
564	          }
565	        }
566	      });
567	
568	      child.stderr.on("data", (chunk: string) => {
569	        process.stderr.write(chunk);
570	      });
571	
572	      child.on("error", (err: Error) => {
573	        if (resultWatchdog !== null) clearTimeout(resultWatchdog);
574	        resolve({ stdout: stdoutChunks.join(""), status: null, signal: null, error: err });
575	      });
576	
577	      child.on("exit", () => {
578	        if (resultWatchdog !== null) clearTimeout(resultWatchdog);
579	        setTimeout(() => {
580	          if (!child.stdout.destroyed) child.stdout.destroy();
581	          if (!child.stderr.destroyed) child.stderr.destroy();
582	        }, 0);
583	      });
584	
585	      child.on("close", (code: number | null, signal: string | null) => {
586	        resolve({ stdout: stdoutChunks.join(""), status: code, signal });
587	      });
588	    });
589	  }
590	
591	  emit({ type: "claude_spawn", task_id: taskId, feature_id: featureId, max_turns: maxTurns });
592	
593	  let spawnResult: SpawnResult | undefined;
594	  let tokenUsage: { input: number; output: number; model: string; cost_usd: number; pricingFallback: boolean } | undefined;
595	  let logFlushed = false;
596	
597	  try {
598	    spawnResult = await spawnClaude(effectiveBriefing, maxTurns);
599	
600	    emit({
601	      type: "claude_exit",
602	      task_id: taskId,
603	      feature_id: featureId,
604	      exit_code: spawnResult.status,
605	      signal: spawnResult.signal ?? null,
606	    });
607	
608	    // ── 7. Token audit ────────────────────────────────────────────────────────
609	    tokenUsage = spawnResult.stdout ? extractTokenUsage(spawnResult.stdout) : undefined;
610	
611	    if (tokenUsage === undefined) {
612	      emit({ type: "budget_audit_skipped", task_id: taskId, reason: "usage format not found" });
613	    } else {
614	      if (tokenUsage.pricingFallback) {
615	        emit({ type: "pricing_fallback", task_id: taskId, model: tokenUsage.model, note: "unknown model — Sonnet rates applied" });
616	      }
617	      emit({
618	        type: "budget_audit",
619	        task_id: taskId,
620	        feature_id: featureId,
621	        total_tokens: tokenUsage.input + tokenUsage.output,
622	        max_tokens: budgetTokens,
623	      });
624	    }
625	
626	    // ── 7a. RAG query audit
627	    if (spawnResult.stdout) {
628	      for (const rq of extractRagQueries(spawnResult.stdout)) {
629	        emit({ type: "rag_query", ...rq });
630	      }
631	    }
632	
633	    // ── 7b. GitNexus query audit
634	    if (spawnResult.stdout) {
635	      for (const gq of extractGitNexusQueries(spawnResult.stdout)) {
636	        emit({ type: "gitnexus_query", ...gq });
637	      }
638	    }
639	
640	    // ── 8. Check for result.json written by Claude ────────────────────────────
641	    // The pr_url is sourced ONLY from Claude's result.json. The executor does not
642	    // scrape stdout for GitHub URLs, and does not synthesize an in_review result
643	    // when Claude exits cleanly without writing result.json — both paths previously
644	    // produced false-positives where unrelated PR URLs (e.g. the workspace claim PR
645	    // echoed via a Read of T<n>.yaml) were captured as the impl PR.
646	
647	    /**
648	     * Read result.json, validate, apply pr_url enforcement + budget check, and
649	     * write the final version back. Returns true if a valid result was processed
650	     * (caller can return), false if no valid result.json exists.
651	     */
652	    const processResultJson = (stdout: string): boolean => {
653	      if (!existsSync(resultPath)) return false;
654	      let raw: unknown;
655	      try {
656	        raw = JSON.parse(readFileSync(resultPath, "utf-8"));
657	      } catch {
658	        return false;
659	      }
660	      if (!isValidResult(raw)) return false;
661	
662	      let claudeResult = raw as ExecutorResult;
663	      if (tokenUsage !== undefined && !claudeResult.token_usage) {
664	        claudeResult.token_usage = { input: tokenUsage.input, output: tokenUsage.output, model: tokenUsage.model };
665	      }
666	      if (tokenUsage !== undefined && claudeResult.cost_usd === undefined) {
667	        claudeResult.cost_usd = tokenUsage.cost_usd;
668	      }
669	
670	      // Refuse terminal_status: in_review without a valid pr_url. Checks:
671	      //   1. pr_url must be present and non-empty.
672	      //   2. pr_url owner/repo must match the task's implementation repo.
673	      //   3. PR head branch must be feature/{featureId}-{taskId} (API-verified).
674	      let prUrlCtx: Parameters<typeof enforceInReviewRequiresPrUrl>[1];
675	      try {
676	        const { owner, repo } = parseGitHubCoords(taskRepoUrl);
677	        prUrlCtx = { expectedOwner: owner, expectedRepo: repo, featureId, taskId, githubToken: githubToken || undefined };
678	      } catch {
679	        prUrlCtx = undefined;
680	      }
681	      const enforced = enforceInReviewRequiresPrUrl(claudeResult, prUrlCtx);
682	      if (enforced.rewritten) {
683	        emit({
684	          type: "in_review_refused_no_pr_url",
685	          task_id: taskId,
686	          feature_id: featureId,
687	          blocked_reason: enforced.result.blocked_reason,
688	        });
689	      }
690	      claudeResult = enforced.result;
691	
692	      if (
693	        budgetTokens !== undefined &&
694	        tokenUsage !== undefined &&
695	        tokenUsage.input + tokenUsage.output > budgetTokens
696	      ) {
697	        writeResult(resultPath, {
698	          terminal_status: "blocked",
699	          blocked_reason: "budget_exceeded",
700	          token_usage: tokenUsage,
701	        });
702	      } else {
703	        writeResult(resultPath, claudeResult);
704	      }
705	
706	      if (logSinkEnabled && workspaceRoot && taskBranch) {
707	        flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, stdout, claudeResult.terminal_status, sshKeyPath, emit);
708	        logFlushed = true;
709	      }
710	      return true;
711	    };
712	
713	    if (processResultJson(spawnResult.stdout)) {
714	      // Valid result.json — Layer 1 recovery (finally block) will no-op.
715	      return;
716	    }
717	
718	    // ── 9. Claude did not write result.json ──────────────────────────────────
719	    // Budget-exceeded: write blocked immediately (deterministic, no recovery side-effects needed).
720	    if (
721	      budgetTokens !== undefined &&
722	      tokenUsage !== undefined &&
723	      tokenUsage.input + tokenUsage.output > budgetTokens
724	    ) {
725	      writeResult(resultPath, {
726	        terminal_status: "blocked",
727	        blocked_reason: "budget_exceeded",
728	        token_usage: tokenUsage,
729	      });
730	      if (logSinkEnabled && workspaceRoot && taskBranch) {
731	        flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, "blocked", sshKeyPath, emit);
732	        logFlushed = true;
733	      }
734	      return;
735	    }
736	
737	    // ── 9b. Continuation retry — Claude exited cleanly without writing result ─
738	    // The headless `-p` session can end on `end_turn` after a sub-skill completes
739	    // its declared steps, even though the outer skill still has work to do. Give
740	    // it one focused retry with a short briefing whose only job is to write
741	    // result.json. Skipped when the first run crashed, was signalled, or hit
742	    // max-turns — those failure modes won't be helped by another attempt.
743	    //
744	    // Review-kind executors have their own recovery path (recovery.recoverReview)
745	    // that checks GitHub for an already-posted review, so they don't need this.
746	    const continuationEligible =
747	      executorKind === "impl" &&
748	      spawnResult.status === 0 &&
749	      !spawnResult.signal &&
750	      !spawnResult.error &&
751	      !isMaxTurnsExit(spawnResult.stdout);
752	
753	    if (continuationEligible) {
754	      const { commitsAhead, workingTreeStatus } = collectGitState(implDir, taskBaseBranch || "main");
755	      const existingPrUrl = fetchOpenPrUrl(taskRepoUrl, taskRepoBranch, githubToken);
756	
757	      const continuationBriefing = generateContinuationBriefing({
758	        taskId,
759	        featureId,
760	        taskBranch: taskRepoBranch,
761	        taskRepoRoot: implDir,
762	        resultPath,
763	        taskBaseBranch: taskBaseBranch || "main",
764	        prUrl: existingPrUrl,
765	        commitsAhead,
766	        workingTreeStatus,
767	      });
768	
769	      emit({
770	        type: "executor_continuation_retry",
771	        task_id: taskId,
772	        feature_id: featureId,
773	        had_pr_url: Boolean(existingPrUrl),
774	      });
775	
776	      const retryMaxTurns = parseInt(
777	        process.env.CONTINUATION_MAX_TURNS ?? String(DEFAULT_CONTINUATION_MAX_TURNS),
778	        10,
779	      );
780	      const retryResult = await spawnClaude(continuationBriefing, retryMaxTurns);
781	
782	      emit({
783	        type: "executor_continuation_complete",
784	        task_id: taskId,
785	        feature_id: featureId,
786	        exit_code: retryResult.status,
787	        signal: retryResult.signal ?? null,
788	      });
789	
790	      // Replace spawnResult so post-hoc recovery (if needed) uses the latest state
791	      // for handover.md and emit. tokenUsage is re-extracted from the retry stdout
792	      // and added to the first-run usage so the audit reflects total tokens spent.
793	      // Preserve first-run stdout — flushLog and recovery use it for forensics.
794	      // Concatenate first-run + retry stdout with a separator so the log sink
795	      // captures both. The retry's stdout alone is the recovery / continuation
796	      // tail; the first run's is where the real work happened.
797	      const firstRunStdout = spawnResult.stdout;
798	      spawnResult = {
799	        ...retryResult,
800	        stdout: firstRunStdout + "\n--- continuation retry stdout ---\n" + retryResult.stdout,
801	      };
802	      const retryUsage = retryResult.stdout ? extractTokenUsage(retryResult.stdout) : undefined;
803	      if (retryUsage !== undefined) {
804	        if (tokenUsage !== undefined) {
805	          // Sum input/output/cost; keep first-run model when both runs used
806	          // the same model (the common case). If models differ, emit a
807	          // pricing_fallback-style warning and use the retry's model so the
808	          // audit reflects the most-recent run. pricingFallback is true if
809	          // either run hit it.
810	          if (tokenUsage.model !== retryUsage.model) {
811	            emit({
812	              type: "continuation_model_mismatch",
813	              task_id: taskId,
814	              feature_id: featureId,
815	              first_run_model: tokenUsage.model,
816	              retry_model: retryUsage.model,
817	              note: "retry used a different model than first run — audit reflects retry's model",
818	            });
819	          }
820	          tokenUsage = {
821	            input: tokenUsage.input + retryUsage.input,
822	            output: tokenUsage.output + retryUsage.output,
823	            model: tokenUsage.model === retryUsage.model ? tokenUsage.model : retryUsage.model,
824	            cost_usd: tokenUsage.cost_usd + retryUsage.cost_usd,
825	            pricingFallback: tokenUsage.pricingFallback || retryUsage.pricingFallback,
826	          };
827	        } else {
828	          tokenUsage = retryUsage;
829	        }
830	      }
831	
832	      if (processResultJson(retryResult.stdout)) {
833	        emit({ type: "executor_continuation_recovered", task_id: taskId, feature_id: featureId });
834	        return;
835	      }
836	
837	      emit({ type: "executor_continuation_failed", task_id: taskId, feature_id: featureId,
838	             note: "retry exited without writing result.json — falling through to post-hoc recovery" });
839	    }
840	
841	    // No result.json produced — recovery will write one in the finally block.
842	
843	  } finally {
844	    // ── Layer 1: post-hoc recovery ────────────────────────────────────────────
845	    // Runs regardless of how the spawn ended. No-op when result.json has a
846	    // valid in_review result (Claude finished cleanly). Otherwise: commits
847	    // uncommitted work, pushes, opens a draft PR, writes handover.md, and
848	    // writes a blocked result.json.
849	    await runRecovery({
850	      spawnResult,
851	      taskId,
852	      featureId,
853	      taskRepoBranch,
854	      taskRepoPath: implDir,
855	      taskRepoUrl,
856	      githubToken,
857	      sshKeyPath,
858	      gitAuthorEmail,
859	      gitAuthorName,
860	      resultPath,
861	      tokenUsage: tokenUsage ? { input: tokenUsage.input, output: tokenUsage.output } : undefined,
862	      kind: executorKind,
863	      implPrUrl: implPrUrl || undefined,
864	      taskBaseBranch: taskBaseBranch || undefined,
865	    });
866	
867	    // Flush log after recovery (best-effort, uses result.json to determine outcome).
868	    // Skip if already flushed in the success or budget-exceeded paths above.
869	    if (!logFlushed && logSinkEnabled && workspaceRoot && taskBranch) {
870	      let outcome = "unknown";
871	      try {
872	        const raw = JSON.parse(readFileSync(resultPath, "utf-8")) as ExecutorResult;
873	        outcome = raw.terminal_status;
874	      } catch { /* ignore */ }
875	      flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult?.stdout ?? "", outcome, sshKeyPath, emit);
876	    }
877	  }
878	}
879	
880	
881	main().catch((e) => {
882	  try {
883	    console.log(JSON.stringify({ type: "fatal_error", details: String(e), at: new Date().toISOString() }));
884	  } catch { /* last resort */ }
885	  process.exit(1);
886	});
