1	/**
2	 * Layer 1 — Executor-side post-hoc recovery routine.
3	 *
4	 * Called from a try/finally around the Claude spawn in index.ts. Guarantees that
5	 * regardless of how Claude exited (clean, max-turns, signal, crash), the task has:
6	 *   - committed any uncommitted work
7	 *   - a PR on the feature branch (draft if no clean PR exists)
8	 *   - a handover.md describing what happened
9	 *   - a valid result.json at resultPath
10	 *
11	 * Idempotent: safe to call multiple times. No-op when the agent already wrote a
12	 * valid result.json with terminal_status "in_review".
13	 *
14	 * Non-throwing: every step is individually wrapped in try/catch. The finally block
15	 * always produces a result.json even if individual side-effects fail.
16	 */
17	
18	import { execSync, spawnSync } from "node:child_process";
19	import {
20	  existsSync,
21	  readFileSync,
22	  writeFileSync,
23	  mkdirSync,
24	} from "node:fs";
25	import { join, dirname } from "node:path";
26	import type { ExecutorResult } from "@workflow/runtime-abi";
27	import { isValidResult } from "@workflow/runtime-abi";
28	import { buildGitEnv } from "./git-env.js";
29	
30	// ── Types ─────────────────────────────────────────────────────────────────────
31	
32	export interface SpawnResult {
33	  stdout: string;
34	  status: number | null;
35	  signal: string | null;
36	  error?: Error;
37	}
38	
39	export interface RecoveryOpts {
40	  /** The result of the Claude spawn, or undefined if the spawn itself failed. */
41	  spawnResult: SpawnResult | undefined;
42	  taskId: string;
43	  featureId: string;
44	  /** The impl repo feature branch (e.g. "feature/my-feature-T3"). */
45	  taskRepoBranch: string;
46	  /** Absolute path to the impl repo working directory. */
47	  taskRepoPath: string;
48	  /** SSH or HTTPS URL of the impl repo — used to derive GitHub coordinates. */
49	  taskRepoUrl: string;
50	  githubToken: string;
51	  sshKeyPath: string | undefined;
52	  gitAuthorEmail: string;
53	  gitAuthorName: string;
54	  /** Absolute path where result.json must be written. */
55	  resultPath: string;
56	  tokenUsage?: { input: number; output: number };
57	  /**
58	   * Executor kind. "review" activates the lightweight reviewer recovery path
59	   * (no commit/push/draft-PR/handover — just checks GitHub for an existing
60	   * review and writes the matching terminal_status). Defaults to "impl".
61	   */
62	  kind?: "impl" | "review";
63	  /**
64	   * For review-kind: the implementation PR URL the reviewer was evaluating.
65	   * Used to look up any review already posted to GitHub before the executor exited.
66	   */
67	  implPrUrl?: string;
68	  /**
69	   * The PR base branch for this task (e.g. "feature/my-feature"). When set,
70	   * draft PRs opened by recovery target this branch instead of the repo default.
71	   */
72	  taskBaseBranch?: string;
73	}
74	
75	// ── Internal helpers ──────────────────────────────────────────────────────────
76	
77	function emitRecovery(event: Record<string, unknown>): void {
78	  console.log(JSON.stringify({ at: new Date().toISOString(), type: "recovery", ...event }));
79	}
80	
81	function curlJson(args: string[]): unknown {
82	  const result = spawnSync("curl", args, {
83	    encoding: "utf-8",
84	    stdio: ["ignore", "pipe", "pipe"],
85	  });
86	  if (result.error) throw result.error;
87	  const stdout = result.stdout ?? "";
88	  if (!stdout.trim()) throw new Error(`curl returned empty response. stderr: ${result.stderr ?? ""}`);
89	  return JSON.parse(stdout);
90	}
91	
92	/**
93	 * Parse GitHub owner/repo from an SSH or HTTPS remote URL.
94	 */
95	export function parseGitHubCoords(repoUrl: string): { owner: string; repo: string } {
96	  const sshMatch = /git@github\.com:([^/]+)\/([^.]+?)(?:\.git)?$/.exec(repoUrl);
97	  if (sshMatch) return { owner: sshMatch[1], repo: sshMatch[2] };
98	  const httpsMatch = /https?:\/\/github\.com\/([^/]+)\/([^/]+?)(?:\.git)?$/.exec(repoUrl);
99	  if (httpsMatch) return { owner: httpsMatch[1], repo: httpsMatch[2] };
100	  throw new Error(`Cannot parse GitHub coords from URL: "${repoUrl}"`);
101	}
102	
103	/**
104	 * Scan stdout for a max-turns exit event from Claude stream-json output.
105	 */
106	export function isMaxTurnsExit(stdout: string): boolean {
107	  for (const line of stdout.split("\n")) {
108	    const trimmed = line.trim();
109	    if (!trimmed.startsWith("{")) continue;
110	    try {
111	      const parsed = JSON.parse(trimmed) as Record<string, unknown>;
112	      if (parsed.type === "result" && parsed.subtype === "error_max_turns") return true;
113	    } catch { /* skip non-JSON lines */ }
114	  }
115	  return false;
116	}
117	
118	/**
119	 * Classify the terminal reason from a spawn result.
120	 */
121	export function detectTerminalReason(spawnResult: SpawnResult | undefined): string {
122	  if (!spawnResult) return "executor_crashed";
123	  if (spawnResult.error) return "executor_spawn_error";
124	  if (spawnResult.signal) return `executor_signal_${spawnResult.signal}`;
125	  if (spawnResult.stdout && isMaxTurnsExit(spawnResult.stdout)) return "max_turns_exceeded";
126	  if (spawnResult.status !== 0) return "executor_crashed";
127	  return "result_not_written";
128	}
129	
130	// ── PR helpers ─────────────────────────────────────────────────────────────────
131	
132	interface PrListItem {
133	  html_url: string;
134	  number: number;
135	}
136	
137	/**
138	 * Find an existing open PR on the branch, or open a new draft PR.
139	 * Returns the PR URL on success, or undefined if all attempts fail.
140	 */
141	function findOrOpenDraftPr(opts: {
142	  taskRepoUrl: string;
143	  taskRepoBranch: string;
144	  taskId: string;
145	  featureId: string;
146	  githubToken: string;
147	  lastCommitSha: string;
148	  taskBaseBranch?: string;
149	}): string | undefined {
150	  try {
151	    const { owner, repo } = parseGitHubCoords(opts.taskRepoUrl);
152	    const encodedHead = encodeURIComponent(`${owner}:${opts.taskRepoBranch}`);
153	    const listUrl =
154	      `https://api.github.com/repos/${owner}/${repo}/pulls` +
155	      `?head=${encodedHead}&state=open`;
156	
157	    const prs = curlJson([
158	      "-s",
159	      "-H", `Authorization: token ${opts.githubToken}`,
160	      "-H", "Accept: application/vnd.github+json",
161	      listUrl,
162	    ]) as PrListItem[];
163	
164	    if (Array.isArray(prs) && prs.length > 0) {
165	      return prs[0].html_url;
166	    }
167	
168	    // No existing PR — open a draft.
169	    // Use the orchestrator-supplied taskBaseBranch (feature branch) when available;
170	    // fall back to the repo's default branch.
171	    let baseBranch = opts.taskBaseBranch ?? "main";
172	    if (!opts.taskBaseBranch) {
173	      try {
174	        const repoMeta = curlJson([
175	          "-s",
176	          "-H", `Authorization: token ${opts.githubToken}`,
177	          "-H", "Accept: application/vnd.github+json",
178	          `https://api.github.com/repos/${owner}/${repo}`,
179	        ]) as { default_branch?: string };
180	        if (repoMeta.default_branch) baseBranch = repoMeta.default_branch;
181	      } catch {
182	        /* fall through to "main" */
183	      }
184	    }
185	
186	    const prTitle = `[WIP] feat(${opts.featureId}/${opts.taskId}): agent terminated — draft PR`;
187	    const prBody = [
188	      `## Task: ${opts.taskId}`,
189	      "",
190	      `**Branch:** \`${opts.taskRepoBranch}\``,
191	      `**Last commit:** ${opts.lastCommitSha}`,
192	      "",
193	      "Agent terminated before completion — see handover.md.",
194	      "",
195	      "_This draft PR was opened by the post-hoc recovery routine._",
196	    ].join("\n");
197	
198	    const createUrl = `https://api.github.com/repos/${owner}/${repo}/pulls`;
199	    const requestBody = JSON.stringify({
200	      title: prTitle,
201	      body: prBody,
202	      head: opts.taskRepoBranch,
203	      base: baseBranch,
204	      draft: true,
205	    });
206	
207	    const created = curlJson([
208	      "-s", "-X", "POST",
209	      "-H", `Authorization: token ${opts.githubToken}`,
210	      "-H", "Accept: application/vnd.github+json",
211	      "-H", "Content-Type: application/json",
212	      "-d", requestBody,
213	      createUrl,
214	    ]) as { html_url?: string; number?: number };
215	
216	    if (!created.html_url) {
217	      emitRecovery({ step: "open_draft_pr", error: `GitHub response missing html_url: ${JSON.stringify(created)}` });
218	      return undefined;
219	    }
220	    return created.html_url;
221	  } catch (e) {
222	    emitRecovery({ step: "find_or_open_draft_pr", error: String(e) });
223	    return undefined;
224	  }
225	}
226	
227	// ── Handover writer ────────────────────────────────────────────────────────────
228	
229	function writeHandover(opts: {
230	  handoverPath: string;
231	  taskId: string;
232	  taskRepoBranch: string;
233	  lastCommitSha: string;
234	  lastCommitMessage: string;
235	  terminalReason: string;
236	  prUrl: string | undefined;
237	  taskRepoPath: string;
238	}): void {
239	  const filesChanged = (() => {
240	    try {
241	      return execSync(
242	        `git -C "${opts.taskRepoPath}" diff --name-status $(git -C "${opts.taskRepoPath}" merge-base HEAD origin/main 2>/dev/null || echo HEAD~1) HEAD`,
243	        { encoding: "utf-8", stdio: "pipe" },
244	      ).trim() || "(no changes detected)";
245	    } catch {
246	      return "(could not determine changed files)";
247	    }
248	  })();
249	
250	  const lines = [
251	    `# Handover — ${opts.taskId}`,
252	    "",
253	    `**Terminal reason:** ${opts.terminalReason}`,
254	    `**Branch:** ${opts.taskRepoBranch}`,
255	    `**Last commit:** ${opts.lastCommitSha} ${opts.lastCommitMessage}`,
256	    `**PR:** ${opts.prUrl ?? "(none opened)"}`,
257	    "",
258	    "## Files modified in this run",
259	    "",
260	    "```",
261	    filesChanged,
262	    "```",
263	    "",
264	    "## Next agent — read this first",
265	    "",
266	    "This handover was written by the post-hoc recovery routine.",
267	    "The agent that produced these commits did not have a chance to",
268	    "write a structured handover. Re-claim the task, read the diff,",
269	    "continue where the last commit left off. If a checkpoint",
270	    "handover.md was written by the agent itself it will appear",
271	    "above this stub — read it first.",
272	  ];
273	
274	  mkdirSync(dirname(opts.handoverPath), { recursive: true });
275	  writeFileSync(opts.handoverPath, lines.join("\n"), "utf-8");
276	}
277	
278	// ── Review-kind recovery ───────────────────────────────────────────────────────
279	
280	/**
281	 * Lightweight recovery for review executors.
282	 *
283	 * The reviewer already posted its GitHub review (APPROVE or REQUEST_CHANGES)
284	 * before running out of turns or crashing — it just never got to write result.json.
285	 * Instead of the full impl recovery (commit/push/draft-PR/handover.md), we simply
286	 * look up the most recent substantive review on the PR and synthesize the correct
287	 * terminal_status from it. No git operations, no handover doc.
288	 */
289	async function recoverReview(opts: {
290	  implPrUrl: string | undefined;
291	  githubToken: string;
292	  taskId: string;
293	  featureId: string;
294	  resultPath: string;
295	  tokenUsage: { input: number; output: number } | undefined;
296	}): Promise<void> {
297	  const { implPrUrl, githubToken, taskId, featureId, resultPath, tokenUsage } = opts;
298	
299	  type TerminalStatus = "passed" | "change_requested" | "escalate";
300	  let terminalStatus: TerminalStatus = "escalate";
301	  let notes = "reviewer exited without writing result.json — no prior GitHub review found";
302	
303	  if (implPrUrl && githubToken) {
304	    try {
305	      const match = /github\.com\/([^/]+)\/([^/]+)\/pull\/(\d+)/.exec(implPrUrl);
306	      if (match) {
307	        const [, owner, repo, pullNumber] = match;
308	        const reviews = curlJson([
309	          "-s",
310	          "-H", `Authorization: Bearer ${githubToken}`,
311	          "-H", "Accept: application/vnd.github+json",
312	          `https://api.github.com/repos/${owner}/${repo}/pulls/${pullNumber}/reviews`,
313	        ]) as Array<{ state: string; submitted_at: string }>;
314	
315	        const substantive = (Array.isArray(reviews) ? reviews : [])
316	          .filter((r) => r.state === "APPROVED" || r.state === "CHANGES_REQUESTED")
317	          .sort((a, b) => new Date(b.submitted_at).getTime() - new Date(a.submitted_at).getTime());
318	
319	        if (substantive.length > 0) {
320	          if (substantive[0].state === "APPROVED") {
321	            terminalStatus = "passed";
322	            notes = "recovered: APPROVE already posted to GitHub before executor exited";
323	          } else {
324	            terminalStatus = "change_requested";
325	            notes = "recovered: REQUEST_CHANGES already posted to GitHub before executor exited";
326	          }
327	        }
328	      }
329	    } catch (e) {
330	      emitRecovery({ step: "fetch_github_reviews", task_id: taskId, feature_id: featureId, error: String(e) });
331	    }
332	  }
333	
334	  try {
335	    const result = {
336	      terminal_status: terminalStatus,
337	      verdict: terminalStatus,
338	      confidence: terminalStatus === "escalate" ? 0.0 : 0.75,
339	      notes,
340	      ...(tokenUsage ? { token_usage: tokenUsage } : {}),
341	    } as unknown as ExecutorResult;
342	    mkdirSync(dirname(resultPath), { recursive: true });
343	    writeFileSync(resultPath, JSON.stringify(result), "utf-8");
344	    emitRecovery({ step: "wrote_result", terminal_status: terminalStatus, task_id: taskId, feature_id: featureId });
345	  } catch (e) {
346	    emitRecovery({ step: "write_result", task_id: taskId, feature_id: featureId, error: String(e) });
347	  }
348	}
349	
350	// ── Public API ─────────────────────────────────────────────────────────────────
351	
352	/**
353	 * Run the post-hoc recovery routine.
354	 *
355	 * For review-kind executors: checks GitHub for an already-posted review and
356	 * writes the matching terminal_status (passed/change_requested/escalate) directly.
357	 * No commit, no push, no draft PR, no handover doc.
358	 *
359	 * For impl-kind executors: commits any dirty work, pushes the branch, opens (or
360	 * reuses) a draft PR, writes handover.md, and writes terminal_status "blocked".
361	 *
362	 * No-op when the executor already wrote a valid result.json.
363	 */
364	export async function runRecovery(opts: RecoveryOpts): Promise<void> {
365	  const {
366	    spawnResult,
367	    taskId,
368	    featureId,
369	    taskRepoBranch,
370	    taskRepoPath,
371	    taskRepoUrl,
372	    githubToken,
373	    sshKeyPath,
374	    gitAuthorEmail,
375	    gitAuthorName,
376	    resultPath,
377	    tokenUsage,
378	    kind = "impl",
379	    implPrUrl,
380	    taskBaseBranch,
381	  } = opts;
382	
383	  // ── 0. No-op when the executor already wrote a valid result ────────────────
384	  if (existsSync(resultPath)) {
385	    try {
386	      const raw = JSON.parse(readFileSync(resultPath, "utf-8")) as Record<string, unknown>;
387	      if (raw && typeof raw === "object" && typeof raw.terminal_status === "string") {
388	        const ts = raw.terminal_status;
389	        // impl: in_review with pr_url → clean completion
390	        if (kind === "impl" && ts === "in_review" && raw.pr_url) return;
391	        // review: any valid reviewer terminal_status → clean completion
392	        if (kind === "review" && (ts === "passed" || ts === "change_requested" || ts === "escalate")) return;
393	      }
394	    } catch { /* fall through to recovery */ }
395	  }
396	
397	  // ── 0b. Review-kind: lightweight result recovery ───────────────────────────
398	  if (kind === "review") {
399	    await recoverReview({ implPrUrl, githubToken, taskId, featureId, resultPath, tokenUsage });
400	    return;
401	  }
402	
403	  emitRecovery({ step: "start", task_id: taskId, feature_id: featureId });
404	
405	  // Preserve existing blocked_reason if Claude produced a valid blocked result.
406	  let existingBlockedReason: string | undefined;
407	  let existingBlockedSuggestion: string | undefined;
408	  if (existsSync(resultPath)) {
409	    try {
410	      const raw = JSON.parse(readFileSync(resultPath, "utf-8")) as unknown;
411	      if (isValidResult(raw)) {
412	        const r = raw as ExecutorResult;
413	        existingBlockedReason = r.blocked_reason;
414	        existingBlockedSuggestion = r.blocked_suggestion;
415	      }
416	    } catch { /* ignore */ }
417	  }
418	
419	  const terminalReason = existingBlockedReason ?? detectTerminalReason(spawnResult);
420	
421	  // ── 1. Commit dirty working tree ───────────────────────────────────────────
422	  let lastCommitSha = "";
423	  let lastCommitMessage = "";
424	  try {
425	    const porcelain = execSync(`git -C "${taskRepoPath}" status --porcelain`, {
426	      encoding: "utf-8",
427	      stdio: "pipe",
428	    }).trim();
429	    if (porcelain) {
430	      const gitEnv = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
431	      execSync(`git -C "${taskRepoPath}" add -A`, { env: gitEnv, stdio: "pipe" });
432	      execSync(
433	        `git -C "${taskRepoPath}" commit -m "wip(${taskId}): incomplete — agent terminated unexpectedly"`,
434	        { env: gitEnv, stdio: "pipe" },
435	      );
436	    }
437	    lastCommitSha = execSync(`git -C "${taskRepoPath}" rev-parse HEAD`, {
438	      encoding: "utf-8",
439	      stdio: "pipe",
440	    }).trim();
441	    lastCommitMessage = execSync(`git -C "${taskRepoPath}" log -1 --format=%s`, {
442	      encoding: "utf-8",
443	      stdio: "pipe",
444	    }).trim();
445	  } catch (e) {
446	    emitRecovery({ step: "commit_dirty_tree", error: String(e) });
447	  }
448	
449	  // ── 2. Push branch (best-effort) ───────────────────────────────────────────
450	  try {
451	    execSync(`git -C "${taskRepoPath}" push origin "${taskRepoBranch}"`, {
452	      env: buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName }),
453	      stdio: "pipe",
454	    });
455	  } catch (e) {
456	    emitRecovery({ step: "push_branch", error: String(e) });
457	  }
458	
459	  // ── 3. Find or open draft PR ───────────────────────────────────────────────
460	  let prUrl: string | undefined;
461	  if (githubToken && taskRepoUrl) {
462	    prUrl = findOrOpenDraftPr({
463	      taskRepoUrl,
464	      taskRepoBranch,
465	      taskId,
466	      featureId,
467	      githubToken,
468	      lastCommitSha,
469	      taskBaseBranch,
470	    });
471	  }
472	
473	  // ── 4. Write handover.md ───────────────────────────────────────────────────
474	  const handoverPath = join(dirname(resultPath), "handover.md");
475	  try {
476	    writeHandover({
477	      handoverPath,
478	      taskId,
479	      taskRepoBranch,
480	      lastCommitSha,
481	      lastCommitMessage,
482	      terminalReason,
483	      prUrl,
484	      taskRepoPath,
485	    });
486	  } catch (e) {
487	    emitRecovery({ step: "write_handover", error: String(e) });
488	  }
489	
490	  // ── 5. Write result.json ───────────────────────────────────────────────────
491	  try {
492	    const result: ExecutorResult = {
493	      terminal_status: "blocked",
494	      blocked_reason: terminalReason,
495	      ...(existingBlockedSuggestion ? { blocked_suggestion: existingBlockedSuggestion } : {}),
496	      ...(tokenUsage ? { token_usage: tokenUsage } : {}),
497	      ...(prUrl ? { pr_url: prUrl } : {}),
498	      ...(existsSync(handoverPath) ? { handover_path: handoverPath } : {}),
499	    };
500	    mkdirSync(dirname(resultPath), { recursive: true });
501	    writeFileSync(resultPath, JSON.stringify(result), "utf-8");
502	    emitRecovery({ step: "wrote_result", terminal_status: "blocked", blocked_reason: terminalReason });
503	  } catch (e) {
504	    emitRecovery({ step: "write_result", error: String(e) });
505	  }
506	}
507

